func (p *Parser) parseBinaryExpr(prec1 int) (expr Expr, err error) {
	x, err := p.parseOperand()
	if err != nil {
		return nil, err
	}
	// COLLATE is a postfix operator and may be repeated.
	for p.peek() == COLLATE {
		collation, err := p.parseCollationClause()
		if err != nil {
			return nil, err
		}
		x = &CollateExpr{X: x, Collation: collation}
	}
	for {
		if p.peek().Precedence() < prec1 {
			return x, nil
		}

		pos, op, err := p.scanBinaryOp()
		if err != nil {
			return nil, err
		}

		switch op {
		case NOTNULL, ISNULL:
			x = &Null{X: x, OpPos: pos, Op: op}
		case IN, NOTIN:
			// Parse right-hand side: either (expr-list), (select-stmt), table-name, or table-function
			y, err := p.parseInExpr()
			if err != nil {
				return x, err
			}
			x = &BinaryExpr{X: x, OpPos: pos, Op: op, Y: y}

		case BETWEEN, NOTBETWEEN:
			// The bounds of a BETWEEN bind tighter than the comparison
			// operators, so parse each one above BETWEEN's own precedence. This
			// keeps the AND that separates the bounds distinct from a boolean
			// AND that follows the whole expression.
			rng := &Range{}
			if rng.X, err = p.parseBinaryExpr(op.Precedence() + 1); err != nil {
				return nil, err
			}
			if p.peek() != AND {
				return nil, p.errorExpected(p.pos, p.tok, "AND")
			}
			rng.And, _, _ = p.scan()
			if rng.Y, err = p.parseBinaryExpr(op.Precedence() + 1); err != nil {
				return nil, err
			}
			x = &BinaryExpr{X: x, OpPos: pos, Op: op, Y: rng}

		default:
			y, err := p.parseBinaryExpr(op.Precedence() + 1)
			if err != nil {
				return nil, err
			}
			bin := &BinaryExpr{X: x, OpPos: pos, Op: op, Y: y}

			// LIKE-family operators may be followed by an optional ESCAPE
			// clause. Its expression binds tighter than the comparison
			// operators, matching SQLite's precedence for ESCAPE.
			if isLikeOp(op) && p.peek() == ESCAPE {
				bin.Escape, _, _ = p.scan()
				if bin.EscapeExpr, err = p.parseBinaryExpr(BITAND.Precedence()); err != nil {
					return nil, err
				}
			}
			x = bin
		}
	}
}

