package sql

import (
	"strings"
	"testing"
)

func TestEdgeProbe(t *testing.T) {
	cases := []string{
		// clause boundary: must stay the clause
		`DELETE FROM t LIMIT returning`,
		`DELETE FROM t ORDER BY returning LIMIT 5 RETURNING id`,
		`INSERT INTO t (x) VALUES (1) ON CONFLICT DO UPDATE SET x=1 RETURNING id`,
		`INSERT INTO t (x) VALUES (1) RETURNING returning`,
		`INSERT INTO t (x) VALUES (1) RETURNING id AS returning`,
		`UPDATE t SET returning = 1`,
		`SELECT returning FROM t`,
		`SELECT * FROM t returning`,
		`DELETE FROM returning WHERE id = 1`,
		`UPDATE t SET x = 1 RETURNING returning`,
		`DELETE FROM t LIMIT returning RETURNING id`,
		`INSERT INTO t returning (x) VALUES (1)`,
		`DELETE FROM t LIMIT 5 OFFSET returning`,
		// alias positions
		`SELECT 1 AS returning`,
		`SELECT * FROM t AS returning`,
		`INSERT INTO t (x) VALUES (1) RETURNING id, id AS returning`,
		// qualified / call
		`SELECT t.returning FROM t`,
		`SELECT returning() `,
		`SELECT * FROM t WHERE returning > 0`,
		`WITH returning AS (SELECT 1) SELECT * FROM returning`,
		// join-word regression probes (must keep working)
		`SELECT * FROM t RIGHT JOIN u ON 1`,
		`SELECT * FROM t FULL JOIN u ON 1`,
		`SELECT * FROM t WINDOW`,
		// legitimate returning clauses still work
		`DELETE FROM t RETURNING *`,
		`UPDATE t SET x=2 RETURNING *, id AS pk, x+1`,
	}
	for _, c := range cases {
		stmt, err := NewParser(strings.NewReader(c)).ParseStatement()
		if err != nil {
			t.Logf("ERR %-65s %v", c, err)
			continue
		}
		// round-trip check
		s := stmt.String()
		if _, err2 := NewParser(strings.NewReader(s)).ParseStatement(); err2 != nil {
			t.Logf("RT-ERR %-61s string=%q err=%v", c, s, err2)
		} else {
			t.Logf("OK  %-65s => %s", c, s)
		}
	}
}
EOF
go test ./... -run TestEdgeProbe -v 2>&1 | head -40

