// isAliasToken returns true if tok can begin an alias: an identifier or a
// string literal, which SQLite accepts as an alias too.
func isAliasToken(tok Token) bool {
	return isIdentToken(tok) || tok == STRING
}

// isTableNameToken returns true if tok can begin a table or view name. A
// fallback (non-reserved) keyword works as an identifier there, but RETURNING
// is excluded at the start of a table reference: it must stay available as the
// clause keyword after DELETE/UPDATE/INSERT. As a bare identifier it is only
// reachable in expression positions (e.g. "LIMIT returning"), mirroring
// SQLite's fallback rule where the keyword yields to the clause grammar.
func isTableNameToken(tok Token) bool {
	return isNameToken(tok) && tok != RETURNING
}

